import {PLOTS,startPlot,collectPlot,ensureCounty,contractStatus,deliverContract} from './county-sim.js?v=county11';
export const GARAGE=Object.freeze({x:-35,z:27});
export const VEHICLES=Object.freeze({tractor:{name:'Meadow E-Tractor',price:0,speed:8,reverse:3,capacity:0,radius:1.15,color:'#709a58',spawn:{x:-38,z:24}},pickup:{name:'County Pickup',price:950,speed:13,reverse:4,capacity:40,radius:1.3,color:'#6c9696',spawn:{x:-31,z:24}}});
export function ensureVehicles(s){if(!s.vehicles)s.vehicles={version:1,owned:{}};if(!s.vehicles.owned.tractor)s.vehicles.owned.tractor={...VEHICLES.tractor.spawn,heading:Math.PI,energy:100,cargo:[]};for(const v of Object.values(s.vehicles.owned)){if(!Array.isArray(v.cargo))v.cargo=[];}return s.vehicles;}
function tx(s,fn){const draft=structuredClone(s),result=fn(draft);Object.assign(s,draft);return result;}
function owned(s,id){if(!VEHICLES[id])throw Error('Unknown vehicle.');const v=ensureVehicles(s).owned[id];if(!v)throw Error('You do not own this vehicle.');return v;}
const nearGarage=v=>Math.hypot(v.x-GARAGE.x,v.z-GARAGE.z)<10;
export function buyVehicle(s,id){return tx(s,t=>{if(!VEHICLES[id]||id==='tractor')throw Error('Choose the pickup.');if(ensureVehicles(t).owned[id])throw Error('You already own this vehicle.');if(t.coins<VEHICLES[id].price)throw Error('The pickup costs 950 available farm coins.');t.coins=Math.round((t.coins-VEHICLES[id].price)*100)/100;return t.vehicles.owned[id]={...VEHICLES[id].spawn,heading:Math.PI,energy:100,cargo:[]};});}
export function rechargeVehicle(s,id){return tx(s,t=>{const v=owned(t,id);if(!nearGarage(v))throw Error('Park at the farm garage to recharge.');if(v.energy>=99.9)throw Error('Battery is already full.');if(t.inventory.power<1)throw Error('Charging uses 1 power from stores.');t.inventory.power--;v.energy=Math.min(100,v.energy+25);return v;});}
export function loadVehicleContract(s,id,contractId){return tx(s,t=>{const v=owned(t,id);if(!nearGarage(v))throw Error('Load at the farm garage.');const r=ensureCounty(t).contracts.find(r=>r.id===contractId);if(!r||contractStatus(t,r)!=='active')throw Error('Choose an active village request.');if(Object.values(t.vehicles.owned).some(v=>v.cargo.some(c=>c.contractId===contractId)))throw Error('This request is already loaded.');if(v.cargo.reduce((n,c)=>n+c.quantity,0)+r.qty>VEHICLES[id].capacity)throw Error('Vehicle capacity exceeded. Deliver or unload some cargo.');if((t.inventory[r.good]||0)<r.qty)throw Error('Not enough available '+r.good+' to load this request.');t.inventory[r.good]-=r.qty;v.cargo.push({contractId:r.id,good:r.good,quantity:r.qty});return r;});}
export function unloadVehicle(s,id){return tx(s,t=>{const v=owned(t,id);if(!nearGarage(v))throw Error('Return to the farm garage to unload.');if(!v.cargo.length)throw Error('No cargo to unload.');for(const c of v.cargo)t.inventory[c.good]=(t.inventory[c.good]||0)+c.quantity;v.cargo=[];return v;});}
export function deliverVehicle(s,id,contractId){return tx(s,t=>{const v=owned(t,id);if(Math.hypot(v.x+72,v.z+45)>6)throw Error('Drive to the delivery depot handover point (-72, -45).');const c=v.cargo.find(x=>x.contractId===contractId);if(!c)throw Error('This delivery is not loaded on this vehicle.');t.inventory[c.good]=(t.inventory[c.good]||0)+c.quantity;const r=deliverContract(t,contractId);t.vehicles.owned[id].cargo=t.vehicles.owned[id].cargo.filter(x=>x.contractId!==contractId);return r;});}
export function tractorWork(s){return tx(s,t=>{const v=owned(t,'tractor'),p=PLOTS.find(p=>p.id==='north-field');if(Math.abs(v.x-p.x)>p.w/2-2||Math.abs(v.z-p.z)>p.d/2-2)throw Error('Drive inside your North Fields to work them.');if(v.energy<5)throw Error('Field work needs 5 battery charge.');const record=ensureCounty(t).plots[p.id];if(!record)throw Error('Buy North Fields first.');let action;if(record.job){collectPlot(t,p.id);action='harvested';}else{startPlot(t,p.id);t.county.plots[p.id].job.readyDay=t.day+1;t.county.plots[p.id].job.method='tractor';action='planted';}t.vehicles.owned.tractor.energy-=5;return action;});}
export function recoverVehicle(s,id){return tx(s,t=>{const v=owned(t,id);if(t.inventory.power<2)throw Error('Recovery uses 2 power from stores.');t.inventory.power-=2;Object.assign(v,VEHICLES[id].spawn,{heading:Math.PI});return v;});}
export function vehicleStep(v,id,input,dt,blocked,motion={speed:0}){
 const spec=VEHICLES[id],step=Math.max(0,Math.min(.05,dt));if(!spec||!step)return {moved:0,blocked:false};
 const target=input.brake||v.energy<=0?0:input.throttle>0?spec.speed:input.throttle<0?-spec.reverse:0,rate=input.brake?20:target===0?7:5;
 motion.speed+=Math.max(-rate*step,Math.min(rate*step,target-motion.speed));
 const heading=v.heading-input.steer*motion.speed/spec.speed*1.8*step,distance=motion.speed*step;
 const nx=v.x+Math.sin(heading)*distance,nz=v.z+Math.cos(heading)*distance;
 let collision=false;for(let i=0;i<8;i++){const a=i*Math.PI/4;if(blocked(nx+Math.sin(a)*spec.radius,nz+Math.cos(a)*spec.radius)){collision=true;break;}}
 for(const side of [-1,1]){const half=id==='tractor'?3.6:3.2;for(const lateral of [-spec.radius,spec.radius])if(blocked(nx+Math.sin(heading)*half*side+Math.cos(heading)*lateral,nz+Math.cos(heading)*half*side-Math.sin(heading)*lateral))collision=true;}
 if(collision){motion.speed=0;return {moved:0,blocked:true};}
 v.heading=heading;v.x=nx;v.z=nz;v.energy=Math.max(0,v.energy-Math.abs(distance)*.09);return {moved:Math.abs(distance),blocked:false};
}
export function exitPosition(v,blocked){for(const side of [1,-1,2,-2]){const a=v.heading+(Math.abs(side)===1?Math.PI/2:0),sign=Math.sign(side),x=v.x+Math.sin(a)*2.9*sign,z=v.z+Math.cos(a)*2.9*sign;if(!blocked(x,z))return {x,z};}return null;}
